// Package webui serves the UI generated by the independent ui Gradle build.
package webui

import (
	"embed"
	"io/fs"
)

// Build copies the generated distribution here before compiling the runtime.
//
//go:embed all:assets
var distribution embed.FS

func Files() fs.FS {
	files, _ := fs.Sub(distribution, "assets")
	return files
}
